def calculate_tau_x_squared(x):
    if x == 1:
        return 1

    factors_x = get_prime_factorization(x)

    # If x = p1^a1 * p2^a2 * ..., then x^2 = p1^(2a1) * p2^(2a2) * ...
    # tau(x^2) = (2a1 + 1) * (2a2 + 1) * ...
    tau_x_squared = 1
    for exponent in factors_x.values():
        tau_x_squared *= (2 * exponent + 1)
    return tau_x_squared

def calculate_N_x(x):
    tau_x_squared = calculate_tau_x_squared(x)
    # N(x) = (tau(x^2) - 1) / 2
    # Since x is an integer, x^2 is a perfect square, tau(x^2) is always odd, 
    # so (tau(x^2) - 1) is always even.
    return (tau_x_squared - 1) // 2

