def get_prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def count_divisors(factors):
    count = 1
    for exponent in factors.values():
        count *= (exponent + 1)
    return count

def get_all_divisors(n):
    factors = get_prime_factorization(n)
    divs = []
    primes = list(factors.keys())
    exponents = list(factors.values())

    import itertools

    for exponents_tuple in itertools.product(*(range(e + 1) for e in exponents)):
        d = 1
        for i, exp in enumerate(exponents_tuple):
            d *= primes[i] ** exp
        divs.append(d)
    return divs

def calculate_N(x):
    if x == 1:
        return 0

    x_sq = x * x
    all_divisors = get_all_divisors(x_sq)
    tau_x_sq = len(all_divisors)

    # C(x) is the count of divisors d of x^2 such that d >= x
    C_x = 0
    for d in all_divisors:
        if d >= x:
            C_x += 1

    N_x = tau_x_sq - C_x
    return N_x

